{"implementation": "def solve(case):
    payload = case["payload"]
    nodes_list = payload["nodes"]
    required_symbols = set(payload["required_symbols"])

    # Validate required fields on every node
    required_node_fields = {"id", "parent", "symbol", "depth", "removable", "utility"}
    for node in nodes_list:
        missing = required_node_fields - set(node.keys())
        if missing:
            raise ValueError(f"Node {node.get('id', '?')!r} missing fields: {missing}")

    # id -> node
    nodes = {n["id"]: n for n in nodes_list}

    # children map and root detection
    children = {nid: [] for nid in nodes}
    root_id = None
    for n in nodes_list:
        if n["parent"] is None:
            if root_id is not None:
                raise ValueError("Multiple root nodes detected")
            root_id = n["id"]
        else:
            parent = n["parent"]
            if parent not in nodes:
                raise ValueError(f"Unknown parent {parent!r} for node {n['id']!r}")
            children[parent].append(n["id"])

    if root_id is None:
        raise ValueError("No root node found")

    # symbol -> [node ids] (insertion order preserved for determinism)
    symbol_to_nodes = {}
    for n in nodes_list:
        sym = n["symbol"]
        if sym not in symbol_to_nodes:
            symbol_to_nodes[sym] = []
        symbol_to_nodes[sym].append(n["id"])

    # Validate every required symbol is present
    for sym in required_symbols:
        if sym not in symbol_to_nodes:
            raise ValueError(f"Required symbol {sym!r} is absent from the tree")

    # Candidate traversal order: deepest first, then lexicographic node ID as tie-break
    candidates = sorted(nodes_list, key=lambda n: (-n["depth"], n["id"]))

    retained = set(nodes.keys())
    removal_order = []

    for node in candidates:
        nid = node["id"]

        # Skip non-removable nodes
        if not node["removable"]:
            continue

        # Skip if it still has retained children
        if any(c in retained for c in children[nid]):
            continue

        # After tentative removal, every required symbol must remain covered
        sym = node["symbol"]
        if sym in required_symbols:
            still_covered = any(
                other_id in retained and other_id != nid
                for other_id in symbol_to_nodes[sym]
            )
            if not still_covered:
                continue

        # Commit removal
        retained.discard(nid)
        removal_order.append(nid)

    return {
        "retained_ids": sorted(retained),
        "removal_order": removal_order
    }
"}
